"""Reproduce historical count defects, then bind corrected count to actual full execution."""
from pathlib import Path
import hashlib,json,subprocess,sys
own=Path(__file__).resolve().parent;old=own/'old';new=own/'new';assert json.loads((own/'M0-FIRST-GATE.json').read_text())['mutationScoringReleased']
def cap(name,args,expected=0):
 r=subprocess.run([sys.executable,str(own/'capture.py'),name,str(new),*map(str,args)],capture_output=True,text=True);d=json.loads((own/'logs'/(name+'.json')).read_text());assert d['exitCode']==expected,(name,r.stderr);return d
base=['--old',old,'--new',new,'--workers','2','--time-limit-ms','600000']
cap('OLD-F2-count',['node',own/'ORIGINAL-F1-TOOL.mjs',*base,'--count','--kinds','observation-successor']);oldf2=own/'OLD-F2-count.json';oldf2.write_bytes((own/'logs/OLD-F2-count.stdout').read_bytes());guard=cap('OLD-F2-count-binding-rejection',['python3',own/'verify_count.py',oldf2,'--out',own/'OLD-F2-count-binding-rejection.json'],1);rejected=json.loads((own/'OLD-F2-count-binding-rejection.json').read_text());assert rejected['expectedAnswers']>0 and 'old/new subject population'in rejected['errors'] and 'executing tool identity'in rejected['errors']
cap('OLD-count-selection',['node',old/'scripts/differential_consent_act_families.mjs',*base,'--count','--kinds','base']);prior=json.loads((own/'logs/OLD-count-selection.stdout').read_text());assert prior['worlds']>prior['byKind']['base']>0
cap('corrected-count-selected',['node',new/'scripts/differential_consent_act_families.mjs',*base,'--count','--kinds','base']);current=own/'COUNT-selected.json';current.write_bytes((own/'logs/corrected-count-selected.stdout').read_bytes());d=json.loads(current.read_text());assert d['selected']['worlds']==prior['byKind']['base'] and d['generated']['worlds']>d['selected']['worlds'] and d['executed']is None
for name,path,extra in [('COUNT-selected',current,[]),('COUNT-full',own/'COUNT-full.json',['--full',own/'M0-full.json'])]:cap(name+'-verified',['python3',own/'verify_count.py',path,'--out',own/(name+'-verified.json'),*extra])
result={'schema':'corrected-count-defect-reproduction/1','oldF2':{'subject':'4dc2af1e57bfc3e09ec8d5839e46c277eb521878','recordSha256':hashlib.sha256(oldf2.read_bytes()).hexdigest(),'bindingOmissionRejected':True,'expectedAnswerDenominator':rejected['expectedAnswers'],'errors':rejected['errors']},'oldSelection':{'subject':'740279435178a882f1c2d526a2a7ea0bf2b52cbc','reportedWorlds':prior['worlds'],'selectedBaseWorlds':prior['byKind']['base'],'wrongGeneratedCountReproduced':True},'corrected':{'generated':d['generated'],'selected':d['selected'],'execution':None,'independentCountAndFullKeysAgree':True},'success':True};(own/'COUNT-REPRODUCTION-RESULT.json').write_text(json.dumps(result,indent=2)+'\n');print('COUNT CONTROLS PASS',flush=True)
